/* Minus-one dialogues: two-voice conversations; Ryan is always role B. B lines carry hint + mark. See tests/content.test.js. */
var DIALOGUES = [
  { id: 'a_bikeshop1', title: 'Na loja de bicicletas', en: 'At the bike shop', topic: 'bike', lvl: 'B1',
    target: 'did + would (polite requests)', terms: 'pretérito perfeito, condicional/imperfeito de cortesia',
    roles: { A: 'Empregado', B: 'Ryan' }, formal: true,
    lines: [
      { r: 'A', pt: 'Boa tarde. Em que posso ajudar?', en: 'Good afternoon. How can I help?' },
      { r: 'B', pt: 'Boa tarde. Furei o pneu de trás ontem e queria trocar a câmara de ar.', en: 'Good afternoon. I punctured the back tyre yesterday and I\'d like to change the inner tube.', hint: 'Furei… e queria…', mark: ['Furei', 'queria'] },
      { r: 'A', pt: 'Com certeza. Sabe que medida é?', en: 'Of course. Do you know what size it is?' },
      { r: 'B', pt: 'Trouxe a bicicleta. Acho que é 700 por 28, mas não tenho a certeza.', en: 'I brought the bike. I think it\'s 700 by 28, but I\'m not sure.', hint: 'Trouxe a bicicleta…', mark: ['Trouxe'] },
      { r: 'A', pt: 'Deixe-me ver… Sim, é 700 por 28. Quer que troque já?', en: 'Let me see… Yes, it\'s 700 by 28. Do you want me to change it now?' },
      { r: 'B', pt: 'Se fosse possível, sim. Podia ver também os travões? Fazem um barulho estranho.', en: 'If it were possible, yes. Could you also check the brakes? They make a strange noise.', hint: 'Se fosse possível… Podia…', mark: ['fosse', 'Podia'] },
      { r: 'A', pt: 'Posso. Quando é que começaram a fazer barulho?', en: 'I can. When did they start making noise?' },
      { r: 'B', pt: 'Começaram na semana passada, depois de uma volta à chuva em Monsanto.', en: 'They started last week, after a ride in the rain in Monsanto.', hint: 'Começaram na semana…', mark: ['Começaram'] },
      { r: 'A', pt: 'Então devem ser as pastilhas. Estão gastas.', en: 'Then it must be the brake pads. They\'re worn.' },
      { r: 'B', pt: 'Quanto custaria trocar tudo?', en: 'How much would it cost to change everything?', hint: 'Quanto custaria…', mark: ['custaria'] },
      { r: 'A', pt: 'Com a câmara de ar, fica em trinta e cinco euros. Está pronta daqui a uma hora.', en: 'With the inner tube, it comes to thirty-five euros. It\'ll be ready in an hour.' },
      { r: 'B', pt: 'Perfeito. Volto às cinco para a vir buscar. Obrigado!', en: 'Perfect. I\'ll come back at five to pick it up. Thanks!', hint: 'Perfeito. Volto às cinco…', mark: ['Volto'] },
    ],
    notes: ['queria / podia = "I\'d like / could you": the polite past, softer than quero / pode', 'a câmara de ar = inner tube; o pneu = tyre; furar = to puncture; as pastilhas = brake pads', 'custaria = would cost (custar → custaria)'] },

  { id: 'a_biketrip1', title: 'A volta a Sintra', en: 'The ride to Sintra', topic: 'bike', lvl: 'B1',
    target: 'did + used to', terms: 'pretérito perfeito vs pretérito imperfeito',
    roles: { A: 'Amigo (Tiago)', B: 'Ryan' }, formal: false,
    lines: [
      { r: 'A', pt: 'Então, como foi a volta a Sintra no sábado?', en: 'So, how was the ride to Sintra on Saturday?' },
      { r: 'B', pt: 'Foi brutal! Saímos às sete e chegámos lá às dez.', en: 'It was amazing! We left at seven and got there at ten.', hint: 'Foi brutal! Saímos…', mark: ['Foi', 'Saímos', 'chegámos'] },
      { r: 'A', pt: 'Às sete? Que madrugada! Foram pela marginal?', en: 'At seven? So early! Did you go along the coast road?' },
      { r: 'B', pt: 'Fomos pela marginal até Cascais e depois subimos pela serra.', en: 'We went along the coast to Cascais and then climbed up through the hills.', hint: 'Fomos pela marginal…', mark: ['Fomos', 'subimos'] },
      { r: 'A', pt: 'A subida da Peninha é dura. Conseguiste fazer tudo a pedalar?', en: 'The Peninha climb is tough. Did you manage it all on the pedals?' },
      { r: 'B', pt: 'Quase. No fim, tive de pôr o pé no chão duas vezes.', en: 'Almost. At the end I had to put my foot down twice.', hint: 'Quase. No fim, tive…', mark: ['tive'] },
      { r: 'A', pt: 'Normal. Tu antes não fazias subidas assim, pois não?', en: 'That\'s normal. You didn\'t use to do climbs like that, did you?' },
      { r: 'B', pt: 'Não. No Canadá andava sempre em estradas planas, perto do lago.', en: 'No. In Canada I always used to ride on flat roads, near the lake.', hint: 'Não. No Canadá andava…', mark: ['andava'] },
      { r: 'A', pt: 'E lá também havia ciclovias?', en: 'And were there bike lanes there too?' },
      { r: 'B', pt: 'Havia algumas, mas no inverno ninguém pedalava por causa da neve.', en: 'There were some, but in winter nobody rode because of the snow.', hint: 'Havia algumas, mas…', mark: ['Havia', 'pedalava'] },
      { r: 'A', pt: 'Faz sentido. Da próxima vez quero ir convosco.', en: 'Makes sense. Next time I want to come with you.' },
      { r: 'B', pt: 'Combinado! Avisei o grupo ontem, vou dizer-lhes que vens.', en: 'Deal! I told the group yesterday, I\'ll tell them you\'re coming.', hint: 'Combinado! Avisei…', mark: ['Avisei'] },
    ],
    notes: ['did (saímos, chegámos, fomos) = finished events; used to (andava, pedalava, havia) = how things were', 'chegámos with the accent = we arrived; chegamos = we arrive', 'pôr o pé no chão = to put a foot down on a climb; a subida = the climb; a marginal = the coast road'] },

  { id: 'a_cafe1', title: 'Na pastelaria', en: 'At the pastry shop', topic: 'cafe', lvl: 'A2',
    target: 'would (polite requests) + pronouns', terms: 'imperfeito de cortesia, pronomes (traga-me, dizer-me)',
    roles: { A: 'Empregada', B: 'Ryan' }, formal: true,
    lines: [
      { r: 'A', pt: 'Bom dia! O que vai ser?', en: 'Good morning! What will it be?' },
      { r: 'B', pt: 'Bom dia. Queria uma meia de leite e um pastel de nata, por favor.', en: 'Good morning. I\'d like a milky coffee and a custard tart, please.', hint: 'Queria uma meia…', mark: ['Queria'] },
      { r: 'A', pt: 'É para comer aqui ou para levar?', en: 'Is it to eat here or to take away?' },
      { r: 'B', pt: 'É para aqui. Podia aquecer-me o pastel?', en: 'For here. Could you warm the pastry up for me?', hint: 'É para aqui. Podia…', mark: ['Podia', 'aquecer-me'] },
      { r: 'A', pt: 'Claro. Quer canela e açúcar em pó?', en: 'Sure. Do you want cinnamon and icing sugar?' },
      { r: 'B', pt: 'Só canela, obrigado. E traga-me também um copo de água, se faz favor.', en: 'Just cinnamon, thanks. And bring me a glass of water too, please.', hint: 'Só canela… traga-me…', mark: ['traga-me'] },
      { r: 'A', pt: 'Com certeza. Mais alguma coisa?', en: 'Of course. Anything else?' },
      { r: 'B', pt: 'Por agora não. Ah, podia dizer-me a senha do wi-fi?', en: 'Not for now. Oh, could you tell me the wi-fi password?', hint: 'Por agora não. Podia…', mark: ['podia', 'dizer-me'] },
      { r: 'A', pt: 'É "nata2024", tudo junto. Está escrita ali na parede.', en: 'It\'s "nata2024", all one word. It\'s written up there on the wall.' },
      { r: 'B', pt: 'Obrigado. Quanto lhe devo?', en: 'Thanks. How much do I owe you?', hint: 'Obrigado. Quanto lhe…', mark: ['lhe'] },
      { r: 'A', pt: 'São três euros e vinte.', en: 'That\'s three euros twenty.' },
      { r: 'B', pt: 'Aqui tem. Pode ficar com o troco.', en: 'Here you are. You can keep the change.', hint: 'Aqui tem. Pode ficar…', mark: ['Pode'] },
    ],
    notes: ['queria / podia = "I\'d like / could you": the polite past, standard at any counter', 'traga-me, dizer-me, aquecer-me: me goes after the verb with a hyphen; quanto lhe devo: before it, after a question word', 'uma meia de leite = half coffee, half milk in a cup; um galão = the same in a tall glass'] },

  { id: 'a_restaurant1', title: 'Na esplanada', en: 'At a restaurant terrace', topic: 'cafe', lvl: 'B1',
    target: 'passive + would', terms: 'voz passiva (ser/estar + particípio), condicional/imperfeito de cortesia',
    roles: { A: 'Empregado', B: 'Ryan' }, formal: true,
    lines: [
      { r: 'A', pt: 'Boa noite. Têm reserva?', en: 'Good evening. Do you have a booking?' },
      { r: 'B', pt: 'Temos. A mesa foi reservada em nome de Ryan, para duas pessoas.', en: 'We do. The table was booked under the name Ryan, for two.', hint: 'Temos. A mesa foi…', mark: ['foi', 'reservada'] },
      { r: 'A', pt: 'Ah, sim. Querem ficar dentro ou na esplanada?', en: 'Ah, yes. Do you want to sit inside or on the terrace?' },
      { r: 'B', pt: 'Preferíamos a esplanada, se não estiver muito frio.', en: 'We\'d prefer the terrace, if it isn\'t too cold.', hint: 'Preferíamos a esplanada…', mark: ['Preferíamos'] },
      { r: 'A', pt: 'Está ótimo lá fora. Façam favor. Aqui está a ementa.', en: 'It\'s lovely outside. Come this way. Here\'s the menu.' },
      { r: 'B', pt: 'O peixe do dia foi apanhado hoje?', en: 'Was the fish of the day caught today?', hint: 'O peixe do dia foi…', mark: ['foi', 'apanhado'] },
      { r: 'A', pt: 'Foi, sim. É dourada, grelhada no carvão.', en: 'Yes, it was. It\'s sea bream, grilled over charcoal.' },
      { r: 'B', pt: 'Então queria a dourada, e a minha namorada gostava do bacalhau à Brás.', en: 'Then I\'d like the bream, and my girlfriend would like the bacalhau à Brás.', hint: 'Então queria… e a minha namorada…', mark: ['queria', 'gostava'] },
      { r: 'A', pt: 'Peço desculpa, o bacalhau à Brás está esgotado. Foi todo vendido ao almoço.', en: 'I\'m sorry, the bacalhau à Brás is sold out. It was all sold at lunch.' },
      { r: 'B', pt: 'Que pena. Então podia trazer duas douradas, por favor?', en: 'What a shame. Then could you bring two breams, please?', hint: 'Que pena. Então podia…', mark: ['podia'] },
      { r: 'A', pt: 'Muito bem. E para beber?', en: 'Very good. And to drink?' },
      { r: 'B', pt: 'Uma garrafa de vinho verde. Seria possível trazer também pão e azeitonas?', en: 'A bottle of vinho verde. Would it be possible to bring bread and olives too?', hint: 'Uma garrafa… Seria possível…', mark: ['Seria'] },
    ],
    notes: ['foi reservada / foi apanhado / foi vendido = was booked / was caught / was sold: ser + participle, agreeing with the noun', 'está esgotado = is sold out (a state, so estar)', 'preferíamos / gostava = we\'d prefer / she\'d like: in speech the imperfeito often replaces the condicional'] },

  { id: 'a_pharmacy1', title: 'Na farmácia', en: 'At the pharmacy', topic: 'health', lvl: 'B1',
    target: 'have been doing lately + would', terms: 'pretérito perfeito composto, imperfeito de cortesia',
    roles: { A: 'Farmacêutica', B: 'Ryan' }, formal: true,
    lines: [
      { r: 'A', pt: 'Boa tarde. Diga, por favor.', en: 'Good afternoon. Go ahead, please.' },
      { r: 'B', pt: 'Boa tarde. Tenho andado com tosse e queria alguma coisa para a garganta.', en: 'Good afternoon. I\'ve had a cough lately and I\'d like something for my throat.', hint: 'Tenho andado com tosse…', mark: ['Tenho andado', 'queria'] },
      { r: 'A', pt: 'Há quanto tempo? Tem tido febre?', en: 'For how long? Have you had a fever?' },
      { r: 'B', pt: 'Há uma semana. Febre não, mas tenho dormido muito mal.', en: 'For a week. No fever, but I\'ve been sleeping really badly.', hint: 'Há uma semana…', mark: ['tenho dormido'] },
      { r: 'A', pt: 'A tosse é seca ou com expetoração?', en: 'Is the cough dry or chesty?' },
      { r: 'B', pt: 'É seca. Tenho tossido mais à noite, quando me deito.', en: 'It\'s dry. I\'ve been coughing more at night, when I lie down.', hint: 'É seca. Tenho tossido…', mark: ['Tenho tossido'] },
      { r: 'A', pt: 'Posso dar-lhe um xarope para a tosse seca. Tem alguma alergia?', en: 'I can give you a syrup for dry cough. Do you have any allergies?' },
      { r: 'B', pt: 'Que eu saiba, não. Também gostava de umas pastilhas para a garganta.', en: 'Not that I know of. I\'d also like some throat lozenges.', hint: 'Que eu saiba, não. Também gostava…', mark: ['gostava'] },
      { r: 'A', pt: 'Tome o xarope três vezes por dia, depois das refeições.', en: 'Take the syrup three times a day, after meals.' },
      { r: 'B', pt: 'Está bem. E se não melhorar?', en: 'OK. And if it doesn\'t get better?', hint: 'Está bem. E se…', mark: ['melhorar'] },
      { r: 'A', pt: 'Se continuar daqui a cinco dias, deve ir ao centro de saúde.', en: 'If it\'s still there in five days, you should go to the health centre.' },
      { r: 'B', pt: 'Combinado. Podia dar-me uma fatura com o meu NIF?', en: 'Deal. Could you give me a receipt with my tax number?', hint: 'Combinado. Podia dar-me…', mark: ['Podia', 'dar-me'] },
    ],
    notes: ['tenho andado com tosse / tenho dormido mal = something that has been going on lately (not "I have done")', 'o xarope = syrup; as pastilhas para a garganta = throat lozenges; a fatura com NIF = receipt with your tax number', 'que eu saiba = as far as I know'] },

  { id: 'a_doctor1', title: 'No centro de saúde', en: 'At the health centre', topic: 'health', lvl: 'B1',
    target: 'used to + that I… (espero que)', terms: 'pretérito imperfeito, conjuntivo presente',
    roles: { A: 'Médica', B: 'Ryan' }, formal: true,
    lines: [
      { r: 'A', pt: 'Bom dia, sente-se. Então, o que o traz cá?', en: 'Good morning, have a seat. So, what brings you here?' },
      { r: 'B', pt: 'Bom dia, doutora. Dói-me o joelho. Antes pedalava todos os dias e não tinha problemas.', en: 'Good morning, doctor. My knee hurts. I used to cycle every day and I had no problems.', hint: 'Dói-me o joelho. Antes…', mark: ['pedalava', 'tinha'] },
      { r: 'A', pt: 'E agora já não pedala?', en: 'And now you don\'t cycle any more?' },
      { r: 'B', pt: 'Agora corro mais, porque mudei de trabalho. Antes ia de bicicleta para o escritório.', en: 'Now I run more, because I changed jobs. I used to go to the office by bike.', hint: 'Agora corro mais… Antes ia…', mark: ['ia'] },
      { r: 'A', pt: 'Estou a ver. A dor aparece durante a corrida ou depois?', en: 'I see. Does the pain come during the run or afterwards?' },
      { r: 'B', pt: 'Mais depois. No dia seguinte custa-me descer escadas.', en: 'More afterwards. The next day it\'s hard for me to go down stairs.', hint: 'Mais depois. No dia seguinte…', mark: ['custa-me'] },
      { r: 'A', pt: 'Deixe-me ver… Parece uma tendinite. Nada de grave.', en: 'Let me see… It looks like tendinitis. Nothing serious.' },
      { r: 'B', pt: 'Ainda bem. Espero que não seja preciso parar de correr.', en: 'Good. I hope I won\'t have to stop running.', hint: 'Ainda bem. Espero que…', mark: ['seja'] },
      { r: 'A', pt: 'Durante duas semanas, é melhor descansar. Pode voltar à bicicleta, com calma.', en: 'For two weeks it\'s better to rest. You can go back to the bike, gently.' },
      { r: 'B', pt: 'Ótimo. Espero que melhore depressa, porque tenho uma prova em dezembro.', en: 'Great. I hope it gets better quickly, because I have a race in December.', hint: 'Ótimo. Espero que…', mark: ['melhore'] },
      { r: 'A', pt: 'Se fizer o que lhe disse, vai correr tudo bem.', en: 'If you do what I told you, it\'ll all go well.' },
      { r: 'B', pt: 'Obrigado, doutora. Quando era miúdo, nunca ia ao médico. Agora venho mais vezes!', en: 'Thanks, doctor. When I was a kid I never used to go to the doctor. Now I come more often!', hint: 'Obrigado… Quando era miúdo…', mark: ['era', 'ia'] },
    ],
    notes: ['used to: pedalava, ia, era, tinha (imperfeito) = how things were before', 'espero que + seja / melhore = "I hope that…" takes the "that I…" form (conjuntivo)', 'dói-me o joelho = my knee hurts; custa-me = it\'s hard for me'] },

  { id: 'a_financas1', title: 'Nas Finanças', en: 'At the tax office', topic: 'errands', lvl: 'B1',
    target: 'passive + pronouns', terms: 'voz passiva (foi entregue, está registado), pronomes de complemento',
    roles: { A: 'Funcionária', B: 'Ryan' }, formal: true,
    lines: [
      { r: 'A', pt: 'Bom dia. Senha quarenta e sete? Faça favor.', en: 'Good morning. Ticket forty-seven? Go ahead.' },
      { r: 'B', pt: 'Bom dia. Mandaram-me esta carta sobre o IRS e não a percebi bem.', en: 'Good morning. They sent me this letter about my tax return and I didn\'t really understand it.', hint: 'Mandaram-me esta carta…', mark: ['Mandaram-me', 'a'] },
      { r: 'A', pt: 'Deixe-me ver. Diz que a sua declaração não foi entregue dentro do prazo.', en: 'Let me see. It says your return wasn\'t submitted before the deadline.' },
      { r: 'B', pt: 'Não foi entregue? Mas eu entreguei-a em junho, pelo Portal das Finanças.', en: 'It wasn\'t submitted? But I submitted it in June, on the tax portal.', hint: 'Não foi entregue? Mas eu…', mark: ['foi entregue', 'entreguei-a'] },
      { r: 'A', pt: 'Tem o comprovativo?', en: 'Do you have the proof?' },
      { r: 'B', pt: 'Tenho, está no meu telemóvel. Posso mostrar-lhe?', en: 'I do, it\'s on my phone. Can I show you?', hint: 'Tenho, está no meu…', mark: ['mostrar-lhe'] },
      { r: 'A', pt: 'Pode. Ah, aqui está. A declaração foi submetida, mas ficou com um erro.', en: 'You can. Ah, here it is. The return was submitted, but it had an error.' },
      { r: 'B', pt: 'Um erro? Ninguém me disse nada.', en: 'An error? Nobody told me anything.', hint: 'Um erro? Ninguém me…', mark: ['me'] },
      { r: 'A', pt: 'O seu NIF está registado com a morada antiga. Por isso a carta foi para lá.', en: 'Your tax number is registered with your old address. That\'s why the letter went there.' },
      { r: 'B', pt: 'Pois, mudei de casa no ano passado. Pode atualizá-la já?', en: 'Right, I moved house last year. Can you update it now?', hint: 'Pois, mudei de casa…', mark: ['atualizá-la'] },
      { r: 'A', pt: 'Posso. Fica já atualizada. Depois corrija a declaração no portal.', en: 'I can. It\'s updated now. Then correct the return on the portal.' },
      { r: 'B', pt: 'Muito obrigado. Se tiver dúvidas, posso ligar-lhe?', en: 'Thank you very much. If I have questions, can I call you?', hint: 'Muito obrigado. Se tiver…', mark: ['ligar-lhe'] },
      { r: 'A', pt: 'É melhor ligar para a linha de apoio. O número está escrito na carta.', en: 'It\'s better to call the helpline. The number is written in the letter.' },
    ],
    notes: ['foi entregue = was submitted (the event); está registado / está escrito = is registered / is written (the state)', 'entreguei-a, atualizá-la: o/a goes after the verb; a final -r drops and a becomes la (atualizar + a = atualizá-la)', 'o comprovativo = proof, receipt; a senha = numbered ticket; a morada = address'] },

  { id: 'a_ctt1', title: 'Nos CTT', en: 'At the post office', topic: 'errands', lvl: 'B1',
    target: 'for me to + would', terms: 'infinitivo pessoal (para eu…), imperfeito de cortesia',
    roles: { A: 'Funcionário', B: 'Ryan' }, formal: true,
    lines: [
      { r: 'A', pt: 'Bom dia. Diga.', en: 'Good morning. Go ahead.' },
      { r: 'B', pt: 'Bom dia. Queria levantar uma encomenda. Deixaram-me este aviso na caixa do correio.', en: 'Good morning. I\'d like to pick up a parcel. They left me this slip in the letterbox.', hint: 'Queria levantar…', mark: ['Queria'] },
      { r: 'A', pt: 'Tem algum documento de identificação?', en: 'Do you have any ID?' },
      { r: 'B', pt: 'Tenho o título de residência. Chega para eu levantar a encomenda?', en: 'I have my residence permit. Is that enough for me to pick up the parcel?', hint: 'Tenho o título… Chega para eu…', mark: ['para eu levantar'] },
      { r: 'A', pt: 'Chega, sim. Um momento… Aqui está. Assine aqui, por favor.', en: 'Yes, it is. One moment… Here it is. Sign here, please.' },
      { r: 'B', pt: 'Obrigado. Também gostava de enviar esta caixa para o Canadá.', en: 'Thanks. I\'d also like to send this box to Canada.', hint: 'Obrigado. Também gostava…', mark: ['gostava'] },
      { r: 'A', pt: 'Normal ou registado? O registado é mais caro, mas pode seguir online.', en: 'Standard or registered? Registered is more expensive, but you can track it online.' },
      { r: 'B', pt: 'Registado, para os meus pais saberem quando chega.', en: 'Registered, so my parents know when it arrives.', hint: 'Registado, para os meus pais…', mark: ['saberem'] },
      { r: 'A', pt: 'Muito bem. Tem de preencher esta declaração para a alfândega.', en: 'Very good. You have to fill in this customs form.' },
      { r: 'B', pt: 'Podia ajudar-me? Não sei bem o que escrever aqui.', en: 'Could you help me? I\'m not sure what to write here.', hint: 'Podia ajudar-me?…', mark: ['Podia', 'ajudar-me'] },
      { r: 'A', pt: 'Escreva só "presente, livros e chocolates" e o valor.', en: 'Just write "gift, books and chocolates" and the value.' },
      { r: 'B', pt: 'Perfeito. Quanto tempo demora para eles a receberem?', en: 'Perfect. How long does it take for them to get it?', hint: 'Perfeito. Quanto tempo…', mark: ['receberem'] },
      { r: 'A', pt: 'Mais ou menos duas semanas.', en: 'About two weeks.' },
    ],
    notes: ['para eu levantar / para os meus pais saberem / para eles receberem = "for me / for them to…": the infinitive takes a person ending', 'queria / gostava / podia = polite "I\'d like / could you"', 'a encomenda = parcel; o aviso = notice slip; registado = tracked; a alfândega = customs'] },

  { id: 'a_phone1', title: 'Combinar o jantar', en: 'Arranging dinner on the phone', topic: 'phone', lvl: 'A2',
    target: 'pronouns + will (vou + infinitive)', terms: 'pronomes (ligo-te, não lhe disse), ir + infinitivo',
    roles: { A: 'Amigo (Tiago)', B: 'Ryan' }, formal: false,
    lines: [
      { r: 'A', pt: 'Estou?', en: 'Hello?' },
      { r: 'B', pt: 'Olá, Tiago! É o Ryan. Liguei-te por causa de amanhã.', en: 'Hi Tiago! It\'s Ryan. I\'m calling you about tomorrow.', hint: 'Olá, Tiago! … Liguei-te…', mark: ['Liguei-te'] },
      { r: 'A', pt: 'Ah, diz! Ainda vamos jantar juntos?', en: 'Ah, go on! Are we still having dinner together?' },
      { r: 'B', pt: 'Vamos! Encontramo-nos às oito no Cais do Sodré?', en: 'We are! Shall we meet at eight at Cais do Sodré?', hint: 'Vamos! Encontramo-nos…', mark: ['Encontramo-nos'] },
      { r: 'A', pt: 'Às oito não consigo. Saio do trabalho às oito e meia.', en: 'I can\'t do eight. I finish work at half past eight.' },
      { r: 'B', pt: 'Não faz mal. Então espero por ti na estação às nove.', en: 'No problem. Then I\'ll wait for you at the station at nine.', hint: 'Não faz mal. Então espero…', mark: ['ti'] },
      { r: 'A', pt: 'Boa. E o restaurante? Já reservaste?', en: 'Great. And the restaurant? Have you booked?' },
      { r: 'B', pt: 'Ainda não. Vou ligar-lhes agora e depois mando-te uma mensagem.', en: 'Not yet. I\'ll call them now and then send you a message.', hint: 'Ainda não. Vou ligar-lhes…', mark: ['ligar-lhes', 'mando-te'] },
      { r: 'A', pt: 'Perfeito. Se houver algum problema, liga-me.', en: 'Perfect. If there\'s any problem, call me.' },
      { r: 'B', pt: 'Está descansado. Não te preocupes, eu trato de tudo.', en: 'Relax. Don\'t worry, I\'ll sort it all out.', hint: 'Está descansado. Não te…', mark: ['te'] },
      { r: 'A', pt: 'Ah, e a Sara também vem. Já lhe disseste?', en: 'Oh, and Sara is coming too. Have you told her?' },
      { r: 'B', pt: 'Não, ainda não lhe disse. Vou mandar-lhe a morada também.', en: 'No, I haven\'t told her yet. I\'ll send her the address too.', hint: 'Não, ainda não lhe…', mark: ['lhe disse', 'mandar-lhe'] },
      { r: 'A', pt: 'Fixe. Então até amanhã! Xau!', en: 'Cool. See you tomorrow then! Bye!' },
    ],
    notes: ['liguei-te, mando-te, encontramo-nos: the pronoun goes after the verb with a hyphen', 'não lhe disse, não te preocupes, já lhe disseste: after não / já the pronoun jumps before the verb', 'vou ligar-lhes / vou mandar-lhe = I\'ll call them / send her: in speech "vou + infinitive" is the normal "will"'] },

  { id: 'a_phone2', title: 'Mudar a consulta', en: 'Moving an appointment', topic: 'phone', lvl: 'B1',
    target: 'would (polite requests) + that I… (talvez / quando)', terms: 'imperfeito de cortesia, conjuntivo presente e futuro',
    roles: { A: 'Rececionista', B: 'Ryan' }, formal: true,
    lines: [
      { r: 'A', pt: 'Clínica Dentária do Areeiro, bom dia.', en: 'Areeiro Dental Clinic, good morning.' },
      { r: 'B', pt: 'Bom dia. Tenho consulta marcada para quinta às dez, mas queria mudar a hora.', en: 'Good morning. I have an appointment on Thursday at ten, but I\'d like to change the time.', hint: 'Bom dia. Tenho consulta… mas queria…', mark: ['queria'] },
      { r: 'A', pt: 'Diga-me o seu nome, por favor.', en: 'Tell me your name, please.' },
      { r: 'B', pt: 'Ryan, com ípsilon. Podia ver se há vaga à tarde?', en: 'Ryan, with a Y. Could you see if there\'s a slot in the afternoon?', hint: 'Ryan… Podia ver…', mark: ['Podia'] },
      { r: 'A', pt: 'Na quinta à tarde está tudo ocupado. Talvez na sexta?', en: 'Thursday afternoon is fully booked. Maybe Friday?' },
      { r: 'B', pt: 'Na sexta talvez seja possível, mas só depois das cinco.', en: 'Friday might be possible, but only after five.', hint: 'Na sexta talvez…', mark: ['seja'] },
      { r: 'A', pt: 'Temos às cinco e meia, com o doutor Nuno.', en: 'We have half past five, with Dr Nuno.' },
      { r: 'B', pt: 'Preferia ficar com a doutora Ana, se não for incómodo.', en: 'I\'d prefer to stay with Dr Ana, if it\'s no trouble.', hint: 'Preferia ficar…', mark: ['Preferia', 'for'] },
      { r: 'A', pt: 'A doutora Ana só tem vaga na próxima semana, segunda às nove.', en: 'Dr Ana only has a slot next week, Monday at nine.' },
      { r: 'B', pt: 'Segunda às nove dá. Espero que não haja muito trânsito!', en: 'Monday at nine works. I hope there isn\'t much traffic!', hint: 'Segunda às nove… Espero que…', mark: ['haja'] },
      { r: 'A', pt: 'Fica então marcado: segunda, às nove, com a doutora Ana.', en: 'So it\'s booked: Monday at nine, with Dr Ana.' },
      { r: 'B', pt: 'Obrigado. Quando chegar, aviso na receção?', en: 'Thanks. When I arrive, do I let reception know?', hint: 'Obrigado. Quando chegar…', mark: ['chegar'] },
      { r: 'A', pt: 'Sim, quando chegar, dê o seu nome na receção. Bom dia!', en: 'Yes, when you arrive, give your name at reception. Have a good day!' },
    ],
    notes: ['queria / podia / preferia = polite "I\'d like / could you / I\'d prefer"', 'talvez seja, espero que não haja, quando chegar: "maybe", "I hope" and "when (later)" take the "that I…" forms', 'a consulta = appointment; marcar / desmarcar = to book / cancel; fica marcado = it\'s booked'] },

  { id: 'a_weekend1', title: 'Praia no sábado', en: 'Beach on Saturday', topic: 'friends', lvl: 'B1',
    target: 'for me to + hei de', terms: 'infinitivo pessoal, haver de + infinitivo',
    roles: { A: 'Amiga (Sara)', B: 'Ryan' }, formal: false,
    lines: [
      { r: 'A', pt: 'Então, o que fazemos no sábado? Praia ou serra?', en: 'So, what are we doing on Saturday? Beach or hills?' },
      { r: 'B', pt: 'Eu voto praia. Hei de ir à Costa antes de o verão acabar de vez.', en: 'I vote beach. I\'m going to get to Costa before summer is over for good.', hint: 'Eu voto praia. Hei de…', mark: ['Hei de'] },
      { r: 'A', pt: 'Boa ideia. Mas como é que vamos? Eu não tenho carro.', en: 'Good idea. But how do we get there? I don\'t have a car.' },
      { r: 'B', pt: 'Eu peço o carro à minha namorada. Ela disse que dava para eu o levar no sábado.', en: 'I\'ll ask my girlfriend for the car. She said it was fine for me to take it on Saturday.', hint: 'Eu peço o carro… para eu…', mark: ['para eu'] },
      { r: 'A', pt: 'A sério? Então eu levo o almoço.', en: 'Really? Then I\'ll bring lunch.' },
      { r: 'B', pt: 'Fixe. Faço uma lista para tu não te esqueceres de nada.', en: 'Cool. I\'ll make a list so you don\'t forget anything.', hint: 'Fixe. Faço uma lista para tu…', mark: ['para tu', 'esqueceres'] },
      { r: 'A', pt: 'Ah! Eu nunca me esqueço de nada. E o Tiago?', en: 'Ha! I never forget anything. What about Tiago?' },
      { r: 'B', pt: 'Ele há de dizer que não pode, como sempre. Mas eu hei de convencê-lo.', en: 'He\'s bound to say he can\'t, as always. But I\'ll make sure I convince him.', hint: 'Ele há de dizer… Mas eu hei de…', mark: ['há de', 'hei de'] },
      { r: 'A', pt: 'Boa sorte. A que horas saímos?', en: 'Good luck. What time do we leave?' },
      { r: 'B', pt: 'Às dez, para nós arranjarmos lugar para estacionar.', en: 'At ten, so we can find a parking spot.', hint: 'Às dez, para nós…', mark: ['arranjarmos'] },
      { r: 'A', pt: 'Combinado. E se chover?', en: 'Deal. And if it rains?' },
      { r: 'B', pt: 'Não vai chover. E se chover, havemos de encontrar uma tasca boa.', en: 'It won\'t rain. And if it does, we\'ll find a good tasca somehow.', hint: 'Não vai chover. E se chover…', mark: ['havemos de'] },
    ],
    notes: ['hei de / há de / havemos de + infinitive = I\'m going to, and I mean it (or "he\'s bound to")', 'para eu levar / para tu não te esqueceres / para nós arranjarmos = for me / you / us to…', 'a Costa = Costa da Caparica; uma tasca = a simple traditional eatery'] },

  { id: 'a_weekend2', title: 'O festival em Almada', en: 'The festival in Almada', topic: 'friends', lvl: 'B1',
    target: 'that I… (espero que / não acho que / talvez) + will', terms: 'conjuntivo presente e futuro, ir + infinitivo',
    roles: { A: 'Rita', B: 'Ryan' }, formal: false,
    lines: [
      { r: 'A', pt: 'Ryan, este fim de semana há um festival de música em Almada. Alinhas?', en: 'Ryan, there\'s a music festival in Almada this weekend. Are you in?' },
      { r: 'B', pt: 'Alinho! Espero que toquem alguma coisa de rock.', en: 'I\'m in! I hope they play some rock.', hint: 'Alinho! Espero que…', mark: ['toquem'] },
      { r: 'A', pt: 'Toca uma banda de Coimbra que é muito boa. Vais gostar.', en: 'There\'s a band from Coimbra playing that\'s really good. You\'ll like it.' },
      { r: 'B', pt: 'Então vou levar a minha namorada. Talvez ela queira vir.', en: 'Then I\'ll bring my girlfriend. Maybe she\'ll want to come.', hint: 'Então vou levar… Talvez ela…', mark: ['vou levar', 'queira'] },
      { r: 'A', pt: 'Claro, quantos mais, melhor. Vamos de barco?', en: 'Sure, the more the merrier. Shall we take the ferry?' },
      { r: 'B', pt: 'Vamos. Mas não acho que haja barcos depois da meia-noite.', en: 'Let\'s. But I don\'t think there are ferries after midnight.', hint: 'Vamos. Mas não acho que…', mark: ['haja'] },
      { r: 'A', pt: 'Há, sim, mas só de hora a hora.', en: 'There are, but only once an hour.' },
      { r: 'B', pt: 'Ainda bem. Quando o concerto acabar, apanhamos o último.', en: 'Good. When the concert ends, we\'ll catch the last one.', hint: 'Ainda bem. Quando o concerto…', mark: ['acabar'] },
      { r: 'A', pt: 'E se estiver a chover?', en: 'And if it\'s raining?' },
      { r: 'B', pt: 'Duvido que chova. A previsão diz que vai estar sol o fim de semana todo.', en: 'I doubt it\'ll rain. The forecast says it\'ll be sunny all weekend.', hint: 'Duvido que…', mark: ['chova', 'vai estar'] },
      { r: 'A', pt: 'Ótimo. Então encontramo-nos no Cais do Sodré às seis?', en: 'Great. So we meet at Cais do Sodré at six?' },
      { r: 'B', pt: 'Combinado. Vou comprar os bilhetes logo à noite, para não esgotarem.', en: 'Deal. I\'ll buy the tickets tonight, so they don\'t sell out.', hint: 'Combinado. Vou comprar…', mark: ['Vou comprar'] },
    ],
    notes: ['espero que toquem, talvez queira, não acho que haja, duvido que chova: hopes, doubts and "maybe" take the "that I…" form', 'quando o concerto acabar = when the concert ends (a future "when" takes the "when I (will) have…" form)', 'alinhar = to be up for something (alinhas? = are you in?); o barco = the ferry across the Tejo'] },
  { id: 'b_coop1', title: 'Uma noite de co-op', en: 'A co-op night online', topic: 'games', lvl: 'B1',
    target: 'have been doing lately + pronouns', terms: 'pretérito perfeito composto, pronomes (dá-me, não me)',
    roles: { A: 'Amigo (Tiago)', B: 'Ryan' }, formal: false,
    lines: [
      { r: 'A', pt: 'Então, estás pronto? Já entrei no servidor.', en: 'So, are you ready? I\'m already on the server.' },
      { r: 'B', pt: 'Quase. Tenho tido problemas com o microfone esta semana. Ouves-me?', en: 'Almost. I\'ve been having problems with the mic this week. Can you hear me?', hint: 'Quase. Tenho tido…', mark: ['tenho tido', 'ouves-me'] },
      { r: 'A', pt: 'Ouço-te mal, mas dá para jogar. Tens jogado muito?', en: 'I can barely hear you, but it\'s fine for playing. Have you been playing much?' },
      { r: 'B', pt: 'Não, tenho trabalhado até tarde. Só tenho jogado ao fim de semana.', en: 'No, I\'ve been working late. I\'ve only been playing at the weekend.', hint: 'Não, tenho trabalhado…', mark: ['tenho trabalhado', 'tenho jogado'] },
      { r: 'A', pt: 'Pois, nota-se. Morreste três vezes no último jogo!', en: 'Yeah, it shows. You died three times in the last game!' },
      { r: 'B', pt: 'Não me lembres disso! Dá-me um minuto para mudar as definições.', en: 'Don\'t remind me! Give me a minute to change the settings.', hint: 'Não me lembres…', mark: ['não me', 'dá-me'] },
      { r: 'A', pt: 'Está bem. Queres que te mande o link do canal de voz outra vez?', en: 'OK. Do you want me to send you the voice channel link again?' },
      { r: 'B', pt: 'Sim, manda-me. E diz-me qual é o plano para esta missão.', en: 'Yes, send it to me. And tell me what the plan is for this mission.', hint: 'Sim, manda-me…', mark: ['manda-me', 'diz-me'] },
      { r: 'A', pt: 'Eu vou à frente e tu cobres-me. Não te esqueças das munições.', en: 'I go in front and you cover me. Don\'t forget the ammo.' },
      { r: 'B', pt: 'Combinado. Ultimamente tenho andado a treinar com a sniper, por isso deixa comigo.', en: 'Deal. I\'ve been practising with the sniper rifle lately, so leave it to me.', hint: 'Combinado. Ultimamente tenho andado…', mark: ['tenho andado'] },
      { r: 'A', pt: 'Vamos ver! Começamos daqui a cinco segundos.', en: 'We\'ll see! We start in five seconds.' },
    ],
    notes: ['tenho jogado / tenho trabalhado = have been playing / working lately (still going on)', 'Pronoun after the verb (dá-me, diz-me); before it after não (não me lembres, não te esqueças)', 'cobrir alguém = to cover someone; as munições = ammo; dá para = it works for'] },

  { id: 'b_release1', title: 'O jogo novo', en: 'The new release', topic: 'games', lvl: 'B1',
    target: 'will + that I… (quando / espero que / talvez)', terms: 'futuro, conjuntivo presente e futuro',
    roles: { A: 'Amiga (Sara)', B: 'Ryan' }, formal: false,
    lines: [
      { r: 'A', pt: 'Já viste que o jogo novo da Nintendo sai na sexta?', en: 'Did you see the new Nintendo game comes out on Friday?' },
      { r: 'B', pt: 'Vi! Quando sair, compro-o logo no primeiro dia.', en: 'I did! When it comes out, I\'m buying it on day one.', hint: 'Vi! Quando sair…', mark: ['quando sair'] },
      { r: 'A', pt: 'Eu também quero, mas é caro. Setenta euros!', en: 'I want it too, but it\'s expensive. Seventy euros!' },
      { r: 'B', pt: 'Pois é. Espero que não seja tão difícil como o último.', en: 'True. I hope it isn\'t as hard as the last one.', hint: 'Pois é. Espero que…', mark: ['espero que', 'seja'] },
      { r: 'A', pt: 'O último era impossível. Desisti a meio.', en: 'The last one was impossible. I gave up halfway.' },
      { r: 'B', pt: 'Eu acabei, mas demorei meses. Este será mais curto, acho eu.', en: 'I finished it, but it took me months. This one will be shorter, I think.', hint: 'Eu acabei, mas…', mark: ['será'] },
      { r: 'A', pt: 'Dizem que tem um modo cooperativo. Jogamos juntos?', en: 'They say it has a co-op mode. Shall we play together?' },
      { r: 'B', pt: 'Claro! Quando tiveres tempo, diz-me e ligamos a consola.', en: 'Of course! When you have time, tell me and we\'ll switch on the console.', hint: 'Claro! Quando tiveres…', mark: ['quando tiveres'] },
      { r: 'A', pt: 'Esta semana não posso, tenho exames.', en: 'I can\'t this week, I have exams.' },
      { r: 'B', pt: 'Não faz mal. Talvez no fim de semana estejas mais livre.', en: 'No problem. Maybe you\'ll be freer at the weekend.', hint: 'Não faz mal. Talvez…', mark: ['talvez', 'estejas'] },
      { r: 'A', pt: 'Talvez. Logo se vê!', en: 'Maybe. We\'ll see!' },
    ],
    notes: ['quando sair / quando tiveres = when it comes out / when you have (future after quando)', 'espero que + seja, talvez + estejas: hopes and maybes take the "that I…" form', 'será = will be; logo se vê = we\'ll see'] },

  { id: 'b_strings1', title: 'Na loja de música', en: 'At the music shop', topic: 'music', lvl: 'B1',
    target: 'would (polite past) + pronouns', terms: 'imperfeito de cortesia, condicional, pronomes',
    roles: { A: 'Funcionário da loja', B: 'Ryan' }, formal: true,
    lines: [
      { r: 'A', pt: 'Boa tarde. Precisa de alguma coisa?', en: 'Good afternoon. Do you need anything?' },
      { r: 'B', pt: 'Boa tarde. Queria um jogo de cordas para guitarra elétrica, calibre dez.', en: 'Good afternoon. I\'d like a set of strings for electric guitar, gauge ten.', hint: 'Boa tarde. Queria…', mark: ['queria'] },
      { r: 'A', pt: 'Temos estas e estas. As segundas duram mais, mas são mais caras.', en: 'We have these and these. The second ones last longer, but they\'re more expensive.' },
      { r: 'B', pt: 'Podia mostrar-me as duas? Gostava de comparar.', en: 'Could you show me both? I\'d like to compare.', hint: 'Podia mostrar-me…', mark: ['podia', 'mostrar-me', 'gostava'] },
      { r: 'A', pt: 'Claro. Aqui estão. Para que tipo de música é?', en: 'Of course. Here they are. What kind of music is it for?' },
      { r: 'B', pt: 'Sobretudo rock. Gravo muito em casa, por isso preferia as que duram mais.', en: 'Mostly rock. I record a lot at home, so I\'d prefer the ones that last longer.', hint: 'Sobretudo rock. Gravo…', mark: ['preferia'] },
      { r: 'A', pt: 'Então levava estas, se fosse a si.', en: 'Then I\'d take these, if I were you.' },
      { r: 'B', pt: 'Está bem, levo essas. E também queria umas palhetas médias.', en: 'OK, I\'ll take those. And I\'d also like some medium picks.', hint: 'Está bem, levo…', mark: ['queria'] },
      { r: 'A', pt: 'Quantas quer? Vendem-se à unidade ou em pacotes de seis.', en: 'How many do you want? They\'re sold singly or in packs of six.' },
      { r: 'B', pt: 'Dê-me um pacote, por favor. Já agora, o senhor sabia dizer-me se fazem afinações aqui?', en: 'Give me a pack, please. By the way, could you tell me if you do set-ups here?', hint: 'Dê-me um pacote…', mark: ['dê-me', 'sabia', 'dizer-me'] },
      { r: 'A', pt: 'Fazemos, sim. Pode deixar a guitarra connosco e fica pronta em dois dias.', en: 'We do. You can leave the guitar with us and it\'s ready in two days.' },
      { r: 'B', pt: 'Ótimo. Então trago-a na segunda-feira.', en: 'Great. Then I\'ll bring it on Monday.', hint: 'Ótimo. Então trago-a…', mark: ['trago-a'] },
      { r: 'A', pt: 'Perfeito. São vinte e três euros, ao todo.', en: 'Perfect. That\'s twenty-three euros altogether.' },
    ],
    notes: ['queria / podia / gostava / preferia = the polite "I\'d like / could you" used in every shop', 'se fosse a si = if I were you (to someone you call o senhor / a senhora)', 'as cordas = strings; a palheta = pick; a afinação = set-up / tuning'] },

  { id: 'b_mix1', title: 'A mistura', en: 'Mixing the track', topic: 'music', lvl: 'B1',
    target: 'did + passive', terms: 'pretérito perfeito, voz passiva (foi gravada, está guardado)',
    roles: { A: 'Amigo da banda (Rui)', B: 'Ryan' }, formal: false,
    lines: [
      { r: 'A', pt: 'Então, como correu a gravação ontem?', en: 'So, how did the recording go yesterday?' },
      { r: 'B', pt: 'Correu bem. Gravei as guitarras todas ontem à noite, em três horas.', en: 'It went well. I recorded all the guitars last night, in three hours.', hint: 'Correu bem. Gravei…', mark: ['correu', 'gravei'] },
      { r: 'A', pt: 'Três horas? Foste rápido! E a voz?', en: 'Three hours? That was quick! And the vocals?' },
      { r: 'B', pt: 'A voz ainda não foi gravada. A Sara só pode na quinta.', en: 'The vocals haven\'t been recorded yet. Sara can only do Thursday.', hint: 'A voz ainda não…', mark: ['foi gravada'] },
      { r: 'A', pt: 'Ok. E a bateria? Ficou bem?', en: 'OK. And the drums? Did they turn out well?' },
      { r: 'B', pt: 'A bateria foi programada no REAPER, mas ainda não está misturada.', en: 'The drums were programmed in REAPER, but they\'re not mixed yet.', hint: 'A bateria foi…', mark: ['foi programada', 'está misturada'] },
      { r: 'A', pt: 'Queres ajuda com a mistura? Posso passar aí amanhã.', en: 'Do you want help with the mix? I can come over tomorrow.' },
      { r: 'B', pt: 'Sim, por favor! Ontem tentei misturar sozinho e ficou horrível.', en: 'Yes, please! Yesterday I tried mixing on my own and it sounded awful.', hint: 'Sim, por favor! Ontem tentei…', mark: ['tentei', 'ficou'] },
      { r: 'A', pt: 'Horrível como?', en: 'Awful how?' },
      { r: 'B', pt: 'O baixo estava alto demais e as guitarras desapareceram.', en: 'The bass was too loud and the guitars disappeared.', hint: 'O baixo estava…', mark: ['desapareceram'] },
      { r: 'A', pt: 'Isso resolve-se com um bocado de equalização. Manda-me o projeto hoje.', en: 'That gets fixed with a bit of EQ. Send me the project today.' },
      { r: 'B', pt: 'Está bem. Já está guardado na pasta partilhada.', en: 'OK. It\'s already saved in the shared folder.', hint: 'Está bem. Já está…', mark: ['está guardado'] },
      { r: 'A', pt: 'Fixe. Amanhã às sete, então?', en: 'Cool. Tomorrow at seven, then?' },
    ],
    notes: ['gravei / tentei / ficou = did, one finished event (ontem)', 'foi gravada = was recorded (the event); está guardado = is saved (the state now)', 'a mistura = the mix; a bateria = drums; o baixo = bass; a pasta partilhada = shared folder'] },

  { id: 'b_router1', title: 'A net está lenta', en: 'The internet is slow', topic: 'tech', lvl: 'B1',
    target: 'passive + have been doing lately', terms: 'voz passiva (está ligado, foi registada), pretérito perfeito composto',
    roles: { A: 'Técnico (apoio ao cliente)', B: 'Ryan' }, formal: true,
    lines: [
      { r: 'A', pt: 'Bom dia, apoio técnico, fala o Carlos. Em que posso ajudar?', en: 'Good morning, tech support, Carlos speaking. How can I help?' },
      { r: 'B', pt: 'Bom dia. A net tem estado muito lenta e tem falhado várias vezes por dia.', en: 'Good morning. The internet has been very slow and has been dropping several times a day.', hint: 'Bom dia. A net tem estado…', mark: ['tem estado', 'tem falhado'] },
      { r: 'A', pt: 'Lamento. O router está ligado neste momento?', en: 'I\'m sorry. Is the router on right now?' },
      { r: 'B', pt: 'Está ligado, sim. As luzes estão todas acesas, mas a do Wi-Fi está a piscar.', en: 'Yes, it\'s on. The lights are all on, but the Wi-Fi one is blinking.', hint: 'Está ligado, sim…', mark: ['está ligado', 'estão todas acesas'] },
      { r: 'A', pt: 'Já experimentou reiniciar o router?', en: 'Have you tried restarting the router?' },
      { r: 'B', pt: 'Já. Tenho-o reiniciado quase todos os dias, mas não resolve.', en: 'Yes. I\'ve been restarting it almost every day, but it doesn\'t fix it.', hint: 'Já. Tenho-o…', mark: ['tenho-o reiniciado'] },
      { r: 'A', pt: 'Vou fazer um teste à sua linha. Um momento, por favor.', en: 'I\'ll run a test on your line. One moment, please.' },
      { r: 'A', pt: 'Pois, há um problema na sua zona. A avaria já foi registada.', en: 'Right, there\'s a problem in your area. The fault has already been logged.' },
      { r: 'B', pt: 'E sabe quando vai ser resolvida?', en: 'And do you know when it will be fixed?', hint: 'E sabe quando…', mark: ['vai ser resolvida'] },
      { r: 'A', pt: 'Os técnicos estão a trabalhar nisso. Deve estar resolvida até amanhã.', en: 'The technicians are working on it. It should be fixed by tomorrow.' },
      { r: 'B', pt: 'Está bem. E se não estiver resolvida, o que faço?', en: 'OK. And if it isn\'t fixed, what do I do?', hint: 'Está bem. E se não…', mark: ['estiver resolvida'] },
      { r: 'A', pt: 'Ligue outra vez para este número e é enviado um técnico a sua casa.', en: 'Call this number again and a technician is sent to your home.' },
      { r: 'B', pt: 'Muito obrigado. Ultimamente tenho trabalhado em casa, por isso preciso mesmo da net.', en: 'Thank you very much. I\'ve been working from home lately, so I really need the internet.', hint: 'Muito obrigado. Ultimamente…', mark: ['tenho trabalhado'] },
    ],
    notes: ['tem estado / tem falhado = has been / has been failing lately (still happening)', 'está ligado = is on (state); foi registada = was logged (event); vai ser resolvida = will be fixed', 'a avaria = fault; reiniciar = to restart; a luz está a piscar = the light is blinking'] },

  { id: 'b_password1', title: 'A palavra-passe', en: 'The forgotten password', topic: 'tech', lvl: 'A2',
    target: 'for me to + pronouns', terms: 'infinitivo pessoal, pronomes (ajudar-me, não te)',
    roles: { A: 'Amiga (Sara)', B: 'Ryan' }, formal: false,
    lines: [
      { r: 'A', pt: 'O que se passa? Estás com cara de quem perdeu alguma coisa.', en: 'What\'s up? You look like someone who lost something.' },
      { r: 'B', pt: 'Esqueci-me da palavra-passe do portátil. Podes ajudar-me?', en: 'I forgot my laptop password. Can you help me?', hint: 'Esqueci-me da…', mark: ['esqueci-me', 'ajudar-me'] },
      { r: 'A', pt: 'Claro. Mostra-me o ecrã.', en: 'Sure. Show me the screen.' },
      { r: 'B', pt: 'Aqui está. Diz-me o que fazer, mas devagar.', en: 'Here it is. Tell me what to do, but slowly.', hint: 'Aqui está. Diz-me…', mark: ['diz-me'] },
      { r: 'A', pt: 'Primeiro, tens de entrar no teu email para receberes o código.', en: 'First, you have to go into your email to get the code.' },
      { r: 'B', pt: 'Para eu receber o código, preciso do telemóvel, não é?', en: 'For me to get the code, I need my phone, right?', hint: 'Para eu receber…', mark: ['para eu receber'] },
      { r: 'A', pt: 'Sim. Dá-me o telemóvel, que eu vejo.', en: 'Yes. Give me the phone and I\'ll have a look.' },
      { r: 'B', pt: 'Toma. Não te rias, mas a palavra-passe era o nome do meu gato.', en: 'Here. Don\'t laugh, but the password was my cat\'s name.', hint: 'Toma. Não te rias…', mark: ['não te rias'] },
      { r: 'A', pt: 'Pronto, já está. Agora escolhe uma nova, mas difícil.', en: 'There, done. Now choose a new one, but a hard one.' },
      { r: 'B', pt: 'Podes escrevê-la num papel para eu não me esquecer?', en: 'Can you write it on a piece of paper so I don\'t forget?', hint: 'Podes escrevê-la…', mark: ['escrevê-la', 'para eu não me esquecer'] },
      { r: 'A', pt: 'Não! Para tu não te esqueceres, usa uma frase de que gostes.', en: 'No! So that you don\'t forget, use a sentence you like.' },
      { r: 'B', pt: 'Boa ideia. Obrigado, Sara. Fico a dever-te um café.', en: 'Good idea. Thanks, Sara. I owe you a coffee.', hint: 'Boa ideia. Obrigado…', mark: ['dever-te'] },
    ],
    notes: ['para receberes / para eu receber / para tu não te esqueceres = for you to / for me to (personal infinitive)', 'Pronoun after the verb (ajudar-me, mostra-me); before it after não (não te rias)', 'a palavra-passe = password; o portátil = laptop; ficar a dever = to owe'] },

  { id: 'b_jantar1', title: 'Jantar em casa da Inês', en: 'Dinner at Inês\'s parents\' house', topic: 'family', lvl: 'B1',
    target: 'did + used to', terms: 'pretérito perfeito, pretérito imperfeito',
    roles: { A: 'Mãe da Inês', B: 'Ryan' }, formal: true,
    lines: [
      { r: 'A', pt: 'Então, Ryan, gostou do bacalhau?', en: 'So, Ryan, did you like the bacalhau?' },
      { r: 'B', pt: 'Gostei muito! Nunca comi um bacalhau tão bom.', en: 'I loved it! I\'ve never eaten such good bacalhau.', hint: 'Gostei muito! Nunca…', mark: ['gostei', 'comi'] },
      { r: 'A', pt: 'Ainda bem. E no Canadá, comia-se muito peixe?', en: 'I\'m glad. And in Canada, did people eat a lot of fish?' },
      { r: 'B', pt: 'Comia-se, mas era mais salmão. A minha mãe fazia salmão todas as sextas.', en: 'Yes, but it was more salmon. My mother used to make salmon every Friday.', hint: 'Comia-se, mas…', mark: ['era', 'fazia'] },
      { r: 'A', pt: 'Que engraçado. E como é que conheceu a Inês?', en: 'How funny. And how did you meet Inês?' },
      { r: 'B', pt: 'Conhecemo-nos num concerto, há três anos. Ela estava ao meu lado e começámos a falar.', en: 'We met at a concert, three years ago. She was next to me and we started talking.', hint: 'Conhecemo-nos num…', mark: ['conhecemo-nos', 'estava', 'começámos'] },
      { r: 'A', pt: 'Ela contou-me que o Ryan tocava numa banda.', en: 'She told me you used to play in a band.' },
      { r: 'B', pt: 'Tocava, sim. Quando vivia em Toronto, ensaiávamos todos os fins de semana.', en: 'I did, yes. When I lived in Toronto, we used to rehearse every weekend.', hint: 'Tocava, sim. Quando vivia…', mark: ['tocava', 'vivia', 'ensaiávamos'] },
      { r: 'A', pt: 'E agora, ainda toca?', en: 'And now, do you still play?' },
      { r: 'B', pt: 'Toco em casa. A semana passada gravei uma música nova.', en: 'I play at home. Last week I recorded a new song.', hint: 'Toco em casa. A semana passada…', mark: ['gravei'] },
      { r: 'A', pt: 'Tem de nos mostrar um dia destes!', en: 'You must show us one of these days!' },
      { r: 'B', pt: 'Com todo o gosto. Mas só se a senhora me der a receita do bacalhau!', en: 'With pleasure. But only if you give me the bacalhau recipe!', hint: 'Com todo o gosto. Mas só se…', mark: ['me der'] },
    ],
    notes: ['comia / fazia / tocava / ensaiávamos = used to (habits in the past)', 'gostei / conhecemo-nos / começámos / gravei = did (one finished event)', 'Older Portuguese people often say "o Ryan" instead of "você"; you answer with "a senhora"'] },

  { id: 'b_almoco1', title: 'Almoço de domingo', en: 'Sunday lunch with Tiago\'s family', topic: 'family', lvl: 'B1',
    target: 'if I were + would', terms: 'conjuntivo imperfeito, condicional (e imperfeito com valor de condicional)',
    roles: { A: 'Pai do Tiago', B: 'Ryan' }, formal: true,
    lines: [
      { r: 'A', pt: 'Então, o Ryan pensa ficar em Portugal para sempre?', en: 'So, Ryan, are you planning to stay in Portugal for good?' },
      { r: 'B', pt: 'Se pudesse, ficava cá para sempre. Gosto muito de Lisboa.', en: 'If I could, I\'d stay here for good. I really like Lisbon.', hint: 'Se pudesse…', mark: ['se pudesse', 'ficava'] },
      { r: 'A', pt: 'E se tivesse de voltar para o Canadá amanhã?', en: 'And if you had to go back to Canada tomorrow?' },
      { r: 'B', pt: 'Se tivesse de voltar, teria muitas saudades do sol e da comida.', en: 'If I had to go back, I\'d really miss the sun and the food.', hint: 'Se tivesse de voltar…', mark: ['se tivesse', 'teria'] },
      { r: 'A', pt: 'E da família? Não tem saudades?', en: 'And your family? Don\'t you miss them?' },
      { r: 'B', pt: 'Tenho, claro. Se os meus pais viessem viver cá, era perfeito.', en: 'I do, of course. If my parents came to live here, it would be perfect.', hint: 'Tenho, claro. Se os meus pais…', mark: ['viessem', 'era'] },
      { r: 'A', pt: 'Isso é que era bom. E o que fazia se ganhasse o Euromilhões?', en: 'That would be great. And what would you do if you won the EuroMillions?' },
      { r: 'B', pt: 'Comprava uma casa no Alentejo e fazia viagens de bicicleta pelo país todo.', en: 'I\'d buy a house in the Alentejo and do bike trips all over the country.', hint: 'Comprava uma casa…', mark: ['comprava', 'fazia'] },
      { r: 'A', pt: 'De bicicleta? Eu, se fosse a si, comprava um carro!', en: 'By bike? If I were you, I\'d buy a car!' },
      { r: 'B', pt: 'Não, não. Se eu tivesse um carro, nunca fazia exercício.', en: 'No, no. If I had a car, I\'d never exercise.', hint: 'Não, não. Se eu tivesse…', mark: ['se eu tivesse', 'fazia'] },
      { r: 'A', pt: 'Lá isso é verdade. Mais um bocadinho de arroz?', en: 'That\'s true enough. A little more rice?' },
      { r: 'B', pt: 'Aceitava, mas já não consigo comer mais nada. Obrigado!', en: 'I\'d love to, but I can\'t eat another thing. Thank you!', hint: 'Aceitava, mas…', mark: ['aceitava'] },
    ],
    notes: ['se pudesse / se tivesse / se fosse = if I could / had / were', 'In speech, ficava / comprava / era often replace ficaria / compraria / seria for "would"', 'se fosse a si = if I were you; ter saudades = to miss'] },

  { id: 'b_canada1', title: 'Os invernos no Canadá', en: 'Winters in Canada', topic: 'canada', lvl: 'A2',
    target: 'used to + did', terms: 'pretérito imperfeito, pretérito perfeito',
    roles: { A: 'Amigo (Tiago)', B: 'Ryan' }, formal: false,
    lines: [
      { r: 'A', pt: 'Diz-me uma coisa: como eram os invernos no Canadá?', en: 'Tell me something: what were the winters like in Canada?' },
      { r: 'B', pt: 'Eram muito frios. Às vezes estavam trinta graus negativos.', en: 'They were very cold. Sometimes it was minus thirty.', hint: 'Eram muito frios…', mark: ['eram', 'estavam'] },
      { r: 'A', pt: 'Trinta negativos? E ias para o trabalho como?', en: 'Minus thirty? And how did you get to work?' },
      { r: 'B', pt: 'Ia de metro. No inverno quase ninguém andava de bicicleta.', en: 'I used to take the metro. In winter almost nobody cycled.', hint: 'Ia de metro…', mark: ['ia', 'andava'] },
      { r: 'A', pt: 'E o que fazias aos fins de semana?', en: 'And what did you use to do at the weekends?' },
      { r: 'B', pt: 'Jogava hóquei com os meus amigos num lago gelado.', en: 'I used to play hockey with my friends on a frozen lake.', hint: 'Jogava hóquei…', mark: ['jogava'] },
      { r: 'A', pt: 'Que giro! E porque é que vieste para Lisboa?', en: 'How cool! And why did you come to Lisbon?' },
      { r: 'B', pt: 'Vim por causa do trabalho, há quatro anos, e gostei logo da cidade.', en: 'I came for work, four years ago, and I liked the city straight away.', hint: 'Vim por causa…', mark: ['vim', 'gostei'] },
      { r: 'A', pt: 'E o primeiro inverno aqui? Foi fácil?', en: 'And the first winter here? Was it easy?' },
      { r: 'B', pt: 'Foi estranho! Passei frio dentro de casa, porque não havia aquecimento.', en: 'It was strange! I was cold indoors, because there was no heating.', hint: 'Foi estranho! Passei…', mark: ['foi', 'passei'] },
      { r: 'A', pt: 'Pois, cá em Portugal as casas são geladas no inverno.', en: 'Yeah, here in Portugal houses are freezing in winter.' },
      { r: 'B', pt: 'É verdade. No Canadá estava frio lá fora, mas em casa andávamos de t-shirt.', en: 'True. In Canada it was cold outside, but at home we used to walk around in t-shirts.', hint: 'É verdade. No Canadá…', mark: ['estava', 'andávamos'] },
    ],
    notes: ['eram / ia / jogava / andávamos = used to (how things were, habits)', 'vim / gostei / passei = did (one finished event)', 'passar frio = to be cold (for a while); o aquecimento = heating'] },

  { id: 'b_canada2', title: 'Saudades do Canadá', en: 'Missing Canada', topic: 'canada', lvl: 'B1',
    target: 'would + hei de', terms: 'condicional / imperfeito de cortesia, haver de + infinitivo',
    roles: { A: 'Amiga (Sara)', B: 'Ryan' }, formal: false,
    lines: [
      { r: 'A', pt: 'Tens saudades do Canadá?', en: 'Do you miss Canada?' },
      { r: 'B', pt: 'Às vezes. Gostava de lá ir este Natal, mas os voos estão caríssimos.', en: 'Sometimes. I\'d like to go there this Christmas, but the flights are really expensive.', hint: 'Às vezes. Gostava…', mark: ['gostava'] },
      { r: 'A', pt: 'Hás de conseguir ir. Quando foi a última vez?', en: 'You\'ll manage to go. When was the last time?' },
      { r: 'B', pt: 'Foi há dois anos. Um dia hei de levar-te lá para conheceres a minha família.', en: 'Two years ago. One day I\'ll take you there so you can meet my family.', hint: 'Foi há dois anos. Um dia…', mark: ['hei de', 'levar-te'] },
      { r: 'A', pt: 'Adorava! Mas o que é que eu comeria lá?', en: 'I\'d love that! But what would I eat there?' },
      { r: 'B', pt: 'Comerias poutine, claro. Havias de gostar, garanto.', en: 'You\'d eat poutine, of course. You\'d love it, I promise.', hint: 'Comerias poutine…', mark: ['comerias', 'havias de gostar'] },
      { r: 'A', pt: 'E o frio? Eu não aguentava.', en: 'And the cold? I couldn\'t stand it.' },
      { r: 'B', pt: 'Eu emprestava-te um casaco. Não te deixava passar frio.', en: 'I\'d lend you a coat. I wouldn\'t let you be cold.', hint: 'Eu emprestava-te…', mark: ['emprestava-te', 'deixava'] },
      { r: 'A', pt: 'E tu, voltarias a viver lá?', en: 'And you, would you go back to live there?' },
      { r: 'B', pt: 'Não sei. Por agora não. Primeiro hei de falar português como deve ser!', en: 'I don\'t know. Not for now. First I\'m going to speak Portuguese properly!', hint: 'Não sei. Por agora não…', mark: ['hei de falar'] },
      { r: 'A', pt: 'Já falas muito bem, Ryan.', en: 'You already speak very well, Ryan.' },
    ],
    notes: ['gostava / emprestava / comerias = would (gostava is the everyday way to say "I\'d like")', 'hei de levar-te / hei de falar = I\'ll make sure I take you / I will speak (a promise)', 'havias de gostar = you\'d love it; passar frio = to be cold'] },

  { id: 'b_aula1', title: 'A apresentação', en: 'Talking to the teacher about the presentation', topic: 'class', lvl: 'B1',
    target: 'that I… (espero que / duvido que) + hei de', terms: 'conjuntivo presente, haver de + infinitivo',
    roles: { A: 'Professora', B: 'Ryan' }, formal: true,
    lines: [
      { r: 'A', pt: 'Então, Ryan, já escolheu o tema da apresentação?', en: 'So, Ryan, have you chosen the topic for your presentation?' },
      { r: 'B', pt: 'Já. Quero falar das viagens de bicicleta em Portugal. Espero que não seja aborrecido.', en: 'Yes. I want to talk about bike trips in Portugal. I hope it isn\'t boring.', hint: 'Já. Quero falar… Espero que…', mark: ['espero que', 'seja'] },
      { r: 'A', pt: 'Nada disso! É um ótimo tema. Para quando acha que fica pronta?', en: 'Not at all! It\'s a great topic. When do you think it\'ll be ready?' },
      { r: 'B', pt: 'Hei de acabar até ao fim do mês. Quero que fique bem feita.', en: 'I\'ll make sure I finish by the end of the month. I want it to be done well.', hint: 'Hei de acabar…', mark: ['hei de', 'quero que', 'fique'] },
      { r: 'A', pt: 'Lembre-se de que a apresentação tem de ter dez minutos.', en: 'Remember that the presentation has to be ten minutes long.' },
      { r: 'B', pt: 'Dez minutos? Duvido que consiga falar tanto tempo sem ler!', en: 'Ten minutes? I doubt I can talk that long without reading!', hint: 'Dez minutos? Duvido que…', mark: ['duvido que', 'consiga'] },
      { r: 'A', pt: 'Consegue, sim. Pode usar algumas notas, mas não leia tudo.', en: 'You can. You can use a few notes, but don\'t read it all.' },
      { r: 'B', pt: 'Está bem. Importa-se que eu traga fotografias e um mapa?', en: 'OK. Do you mind if I bring photos and a map?', hint: 'Está bem. Importa-se que…', mark: ['traga'] },
      { r: 'A', pt: 'Claro que não, é uma boa ideia. Assim os colegas percebem melhor.', en: 'Of course, it\'s a good idea. That way the others understand better.' },
      { r: 'B', pt: 'Ótimo. E espero que a professora tenha tempo para ver o meu texto antes.', en: 'Great. And I hope you have time to look at my text beforehand.', hint: 'Ótimo. E espero que…', mark: ['espero que', 'tenha'] },
      { r: 'A', pt: 'Mande-me o texto por email e eu vejo.', en: 'Send me the text by email and I\'ll look at it.' },
      { r: 'B', pt: 'Combinado. Hei de praticar todos os dias até lá!', en: 'Deal. I\'ll make sure I practise every day until then!', hint: 'Combinado. Hei de…', mark: ['hei de'] },
    ],
    notes: ['espero que seja / duvido que consiga / quero que fique = the "that I…" form after hopes, doubts and wants', 'hei de acabar / hei de praticar = I\'ll make sure I finish / practise', '"A professora tem tempo…?" is the polite way to say "do you have time…?" to a teacher'] },

  { id: 'b_aula2', title: 'Os trabalhos de casa', en: 'Homework with a classmate', topic: 'class', lvl: 'B1',
    target: 'for me to + have been doing lately', terms: 'infinitivo pessoal, pretérito perfeito composto',
    roles: { A: 'Colega (Marta)', B: 'Ryan' }, formal: false,
    lines: [
      { r: 'A', pt: 'Olá, Ryan! Fizeste os trabalhos de casa?', en: 'Hi, Ryan! Did you do the homework?' },
      { r: 'B', pt: 'Fiz metade. Tenho andado muito ocupado esta semana.', en: 'I did half. I\'ve been really busy this week.', hint: 'Fiz metade. Tenho andado…', mark: ['tenho andado'] },
      { r: 'A', pt: 'Eu também. Tenho trabalhado até às oito todos os dias.', en: 'Me too. I\'ve been working until eight every day.' },
      { r: 'B', pt: 'Que chatice. Olha, podes explicar-me o exercício três para eu perceber?', en: 'What a pain. Listen, can you explain exercise three so I understand it?', hint: 'Que chatice. Olha, podes…', mark: ['para eu perceber'] },
      { r: 'A', pt: 'Claro. É sobre o infinitivo pessoal: para nós irmos, para eles saberem.', en: 'Sure. It\'s about the personal infinitive: for us to go, for them to know.' },
      { r: 'B', pt: 'Ah, então: a professora deu-nos o texto para lermos em casa?', en: 'Oh, so: the teacher gave us the text for us to read at home?', hint: 'Ah, então: a professora deu-nos…', mark: ['para lermos'] },
      { r: 'A', pt: 'Exatamente! Estás a perceber.', en: 'Exactly! You\'re getting it.' },
      { r: 'B', pt: 'Tenho estudado mais, mas esqueço-me sempre das terminações.', en: 'I\'ve been studying more, but I always forget the endings.', hint: 'Tenho estudado mais…', mark: ['tenho estudado'] },
      { r: 'A', pt: 'Queres estudar comigo antes da aula de quinta?', en: 'Do you want to study with me before Thursday\'s class?' },
      { r: 'B', pt: 'Boa ideia! Podemos ir ao café às seis, para termos tempo antes da aula.', en: 'Good idea! We can go to the café at six, so we have time before class.', hint: 'Boa ideia! Podemos…', mark: ['para termos'] },
      { r: 'A', pt: 'Combinado. Eu levo as fotocópias.', en: 'Deal. I\'ll bring the photocopies.' },
      { r: 'B', pt: 'E eu pago os cafés. Tens sido uma grande ajuda!', en: 'And I\'ll pay for the coffees. You\'ve been a big help!', hint: 'E eu pago…', mark: ['tens sido'] },
    ],
    notes: ['para eu perceber / para lermos / para termos = for me / us to… (personal infinitive)', 'tenho andado / tenho estudado / tens sido = have been doing lately (still going on)', 'os trabalhos de casa = homework; as terminações = endings; que chatice = what a pain'] },
];
if (typeof module !== 'undefined') module.exports = { DIALOGUES };
